import{_ as r,o as e,c as s,a2 as t}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"SSH 公钥管理指南","description":"","frontmatter":{"title":"SSH 公钥管理指南"},"headers":[],"relativePath":"ops-knowledge-base/vps/ssh-key-management-guide.md","filePath":"ops-knowledge-base/vps/ssh-key-management-guide.md","lastUpdated":1788259091000}'),o={name:"ops-knowledge-base/vps/ssh-key-management-guide.md"};function l(i,a,n,h,p,S){return e(),s("div",null,[...a[0]||(a[0]=[t('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档介绍如何在 Raksmart 客户后台创建、导入及管理 SSH 公钥，并说明 SSH 公钥的使用场景，帮助您使用 SSH Key 进行服务器身份认证，提高 Linux 服务器登录的安全性。</p><p><strong>适用产品：</strong></p><ul><li>裸机云（Bare Metal Cloud）</li><li>VPS</li></ul><hr><h2 id="一、什么是-ssh-公钥" tabindex="-1">一、什么是 SSH 公钥？ <a class="header-anchor" href="#一、什么是-ssh-公钥" aria-label="Permalink to &quot;一、什么是 SSH 公钥？&quot;">​</a></h2><p>SSH Key（SSH 密钥）是一种基于公钥与私钥配对的身份认证方式，相较于传统密码登录更加安全。</p><p>一组 SSH Key 由两部分组成：</p><ul><li><strong>公钥（Public Key）</strong>：保存至服务器或 Raksmart 后台，用于验证身份。</li><li><strong>私钥（Private Key）</strong>：保存在本地电脑，用于登录服务器。</li></ul><p>登录服务器时，客户端使用私钥进行身份认证，服务器则通过对应的公钥完成验证。</p><blockquote><p><strong>说明：</strong></p><p>创建 SSH 密钥对后，系统会自动下载私钥文件（<strong>id_rsa.pem</strong>），后台仅保存对应的公钥，不会保存私钥。</p></blockquote><hr><h2 id="二、进入-ssh-公钥管理页面" tabindex="-1">二、进入 SSH 公钥管理页面 <a class="header-anchor" href="#二、进入-ssh-公钥管理页面" aria-label="Permalink to &quot;二、进入 SSH 公钥管理页面&quot;">​</a></h2><ol><li>登录 <strong>Raksmart 客户后台</strong>。</li><li>进入 <strong>会员中心</strong>。</li><li>点击 <strong>技术支持</strong>。</li><li>选择 <strong>SSH 公钥</strong>。</li></ol><p>进入页面后，可查看当前已创建的 SSH 公钥，并进行新增或管理操作。</p><hr><h2 id="三、添加-ssh-公钥" tabindex="-1">三、添加 SSH 公钥 <a class="header-anchor" href="#三、添加-ssh-公钥" aria-label="Permalink to &quot;三、添加 SSH 公钥&quot;">​</a></h2><p>点击页面上方 <strong>添加</strong> 按钮，系统将弹出 <strong>添加信息</strong> 窗口。</p><p>在创建前，请先选择适合自己的方式。</p><blockquote><p><strong>说明：</strong></p><ul><li><strong>首次使用 SSH Key</strong>，建议选择 <strong>创建新密钥对</strong>，系统会自动生成一组公钥和私钥。</li><li><strong>如果您已经拥有 SSH 公钥</strong>，可选择 <strong>使用已有公钥</strong>，直接导入现有公钥，无需重新生成。</li></ul></blockquote><hr><h2 id="_1、名称" tabindex="-1">1、名称 <a class="header-anchor" href="#_1、名称" aria-label="Permalink to &quot;1、名称&quot;">​</a></h2><p>请输入一个便于识别的名称，例如：</p><ul><li>Office-PC</li><li>Laptop</li><li>Linux-Server</li></ul><p>建议根据设备名称或用途进行命名，方便后续管理。</p><hr><h2 id="_2、方式" tabindex="-1">2、方式 <a class="header-anchor" href="#_2、方式" aria-label="Permalink to &quot;2、方式&quot;">​</a></h2><p>目前支持以下两种方式：</p><h3 id="方式一-创建新密钥对-推荐" tabindex="-1">方式一：创建新密钥对（推荐） <a class="header-anchor" href="#方式一-创建新密钥对-推荐" aria-label="Permalink to &quot;方式一：创建新密钥对（推荐）&quot;">​</a></h3><p>选择 <strong>创建新密钥对</strong> 后，系统将自动生成一组 SSH 密钥。</p><p>创建成功后：</p><ul><li>浏览器会自动下载私钥文件 <strong>id_rsa.pem</strong>；</li><li>后台会自动保存对应的公钥。</li></ul><blockquote><p><strong>重要说明：</strong></p><p><strong>id_rsa.pem 为 SSH 私钥文件，仅在创建时提供一次下载，请务必妥善保存。</strong></p><p>如私钥文件遗失，将无法再次下载，只能重新创建新的 SSH 密钥对。</p></blockquote><hr><h3 id="方式二-使用已有公钥" tabindex="-1">方式二：使用已有公钥 <a class="header-anchor" href="#方式二-使用已有公钥" aria-label="Permalink to &quot;方式二：使用已有公钥&quot;">​</a></h3><p>如果您已经拥有 SSH 公钥，可选择 <strong>使用已有公钥</strong>。</p><p>只需将已有的公钥内容粘贴至对应输入框即可完成导入。</p><blockquote><p><strong>说明：</strong></p><p>导入时仅需填写公钥内容，无需上传私钥文件。</p></blockquote><hr><h2 id="_3、加密方法" tabindex="-1">3、加密方法 <a class="header-anchor" href="#_3、加密方法" aria-label="Permalink to &quot;3、加密方法&quot;">​</a></h2><p>目前支持以下加密算法：</p><ul><li>ssh-rsa</li><li>ssh-dss</li><li>ecdsa-sha2-nistp521</li><li>ssh-ed25519</li></ul><p>请选择符合您使用环境的加密算法。</p><blockquote><p><strong>建议：</strong></p><p>推荐优先使用 <strong>ssh-ed25519</strong> 或 <strong>ssh-rsa</strong>，兼容性及安全性较好。</p></blockquote><hr><h2 id="_4、提交" tabindex="-1">4、提交 <a class="header-anchor" href="#_4、提交" aria-label="Permalink to &quot;4、提交&quot;">​</a></h2><p>确认填写信息无误后，点击 <strong>提交</strong> 完成 SSH 公钥创建。</p><p>如需取消本次操作，可点击 <strong>关闭</strong>。</p><hr><h2 id="四、管理-ssh-公钥" tabindex="-1">四、管理 SSH 公钥 <a class="header-anchor" href="#四、管理-ssh-公钥" aria-label="Permalink to &quot;四、管理 SSH 公钥&quot;">​</a></h2><p>创建完成后，SSH 公钥将显示在公钥管理列表中。</p><p>您可以查看公钥的基本信息，例如：</p><ul><li>名称</li><li>公钥内容</li><li>加密算法</li><li>创建时间（如后台显示）</li></ul><p>如不再使用某个 SSH 公钥，也可在管理列表中将其删除。</p><hr><h2 id="五、ssh-公钥的使用场景" tabindex="-1">五、SSH 公钥的使用场景 <a class="header-anchor" href="#五、ssh-公钥的使用场景" aria-label="Permalink to &quot;五、SSH 公钥的使用场景&quot;">​</a></h2><p>SSH 公钥主要用于 Linux 系统的身份认证。</p><p>在以下场景中，可选择使用 SSH 公钥登录：</p><ul><li>创建裸机云实例</li><li>重装 Linux 系统</li><li>其他支持 SSH Key 登录的产品</li></ul><p>当登录方式选择 <strong>SSH 公钥</strong> 时，只需选择已创建的 SSH 公钥即可。</p><p>系统会自动将对应的公钥写入服务器，实现 SSH Key 登录认证。</p><blockquote><p><strong>说明：</strong></p><p>SSH 公钥创建完成后，如需了解如何使用私钥登录服务器，请参考：</p><p><strong>《<a href="https://billing.raksmart.com/whmcs/index.php?rp=/knowledgebase/977/%E5%A6%82%E4%BD%95%E4%BD%BF%E7%94%A8%E7%A7%81%E9%92%A5%E8%BF%9B%E8%A1%8C%E8%BF%9C%E7%A8%8B%E7%99%BB%E5%BD%95.html" target="_blank" rel="noreferrer">如何使用 SSH 私钥远程登录 Linux 服务器</a>》</strong></p></blockquote><hr><h2 id="六、常见问题" tabindex="-1">六、常见问题 <a class="header-anchor" href="#六、常见问题" aria-label="Permalink to &quot;六、常见问题&quot;">​</a></h2><h3 id="q1-什么是-id-rsa-pem-文件" tabindex="-1">Q1：什么是 id_rsa.pem 文件？ <a class="header-anchor" href="#q1-什么是-id-rsa-pem-文件" aria-label="Permalink to &quot;Q1：什么是 id\\_rsa.pem 文件？&quot;">​</a></h3><p>id_rsa.pem 是系统自动生成的 <strong>SSH 私钥文件</strong>。</p><p>登录服务器时，需要使用该私钥进行身份认证，请妥善保存在本地电脑，不要泄露给他人。</p><hr><h3 id="q2-为什么后台只能看到公钥-而看不到私钥" tabindex="-1">Q2：为什么后台只能看到公钥，而看不到私钥？ <a class="header-anchor" href="#q2-为什么后台只能看到公钥-而看不到私钥" aria-label="Permalink to &quot;Q2：为什么后台只能看到公钥，而看不到私钥？&quot;">​</a></h3><p>为了保障账户安全，后台仅保存公钥。</p><p>私钥仅会在创建 SSH 密钥对时提供一次下载，后续无法再次查看或下载。</p><hr><h3 id="q3-私钥丢失怎么办" tabindex="-1">Q3：私钥丢失怎么办？ <a class="header-anchor" href="#q3-私钥丢失怎么办" aria-label="Permalink to &quot;Q3：私钥丢失怎么办？&quot;">​</a></h3><p>私钥无法恢复。</p><p>如私钥遗失，请重新创建新的 SSH 密钥对，并重新将新的公钥应用到服务器。</p><hr><h3 id="q4-ssh-公钥可以用于-windows-登录吗" tabindex="-1">Q4：SSH 公钥可以用于 Windows 登录吗？ <a class="header-anchor" href="#q4-ssh-公钥可以用于-windows-登录吗" aria-label="Permalink to &quot;Q4：SSH 公钥可以用于 Windows 登录吗？&quot;">​</a></h3><p>SSH 公钥主要用于 Linux 系统的 SSH 登录。</p><p>Windows 是否支持 SSH Key 登录，取决于服务器是否已安装并配置 OpenSSH 等相关服务。</p><hr><h3 id="q5-什么时候建议使用-ssh-公钥登录" tabindex="-1">Q5：什么时候建议使用 SSH 公钥登录？ <a class="header-anchor" href="#q5-什么时候建议使用-ssh-公钥登录" aria-label="Permalink to &quot;Q5：什么时候建议使用 SSH 公钥登录？&quot;">​</a></h3><p>建议在以下场景使用：</p><ul><li>日常远程管理 Linux 服务器；</li><li>自动化运维；</li><li>批量管理服务器；</li><li>提高服务器登录安全性；</li><li>避免使用密码登录带来的安全风险。</li></ul><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>⚠️ <strong>id_rsa.pem（私钥）仅会在创建时提供一次下载，请务必及时保存。</strong></p><p>⚠️ 私钥属于敏感信息，请勿发送给他人或上传至公共网络。</p><p>⚠️ 后台仅保存公钥，不保存私钥，私钥无法再次下载。</p><p>⚠️ 如私钥遗失，请重新创建新的 SSH 密钥对，并重新配置服务器。</p><p>⚠️ 建议根据实际使用环境选择合适的加密算法，推荐优先使用 <strong>ssh-ed25519</strong> 或 <strong>ssh-rsa</strong>。</p><hr>',91)])])}const g=r(o,[["render",l]]);export{u as __pageData,g as default};
